// SetGpu of the usuario to the related item.
// Sets o.R.Gpu to related.
// Adds o to related.R.GpuUsuarios.
func (o *Usuario) SetGpu(ctx context.Context, exec boil.ContextExecutor, insert bool, related *GrupoUsuario) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE `usuario` SET %s WHERE %s",
		strmangle.SetParamNames("`", "`", 0, []string{"gpu_id"}),
		strmangle.WhereClause("`", "`", 0, usuarioPrimaryKeyColumns),
	)
	values := []interface{}{related.GpuID, o.UsuID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	o.GpuID = related.GpuID
	if o.R == nil {
		o.R = &usuarioR{
			Gpu: related,
		}
	} else {
		o.R.Gpu = related
	}

	if related.R == nil {
		related.R = &grupoUsuarioR{
			GpuUsuarios: UsuarioSlice{o},
		}
	} else {
		related.R.GpuUsuarios = append(related.R.GpuUsuarios, o)
	}

	return nil
}

