// SetUsuDocumentoVendas removes all previously related items of the
// usuario replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.Usu's UsuDocumentoVendas accordingly.
// Replaces o.R.UsuDocumentoVendas with related.
// Sets related.R.Usu's UsuDocumentoVendas accordingly.
func (o *Usuario) SetUsuDocumentoVendas(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*DocumentoVenda) error {
	query := "update `documento_venda` set `usu_id` = null where `usu_id` = ?"
	values := []interface{}{o.UsuID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.UsuDocumentoVendas {
			queries.SetScanner(&rel.UsuID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.Usu = nil
		}
		o.R.UsuDocumentoVendas = nil
	}

	return o.AddUsuDocumentoVendas(ctx, exec, insert, related...)
}

// RemoveUsuDocumentoVendas relationships from objects passed in.
// Removes related items from R.UsuDocumentoVendas (uses pointer comparison, removal does not keep order)
// Sets related.R.Usu.
func (o *Usuario) RemoveUsuDocumentoVendas(ctx context.Context, exec boil.ContextExecutor, related ...*DocumentoVenda) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.UsuID, nil)
		if rel.R != nil {
			rel.R.Usu = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("usu_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.UsuDocumentoVendas {
			if rel != ri {
				continue
			}

			ln := len(o.R.UsuDocumentoVendas)
			if ln > 1 && i < ln-1 {
				o.R.UsuDocumentoVendas[i] = o.R.UsuDocumentoVendas[ln-1]
			}
			o.R.UsuDocumentoVendas = o.R.UsuDocumentoVendas[:ln-1]
			break
		}
	}

	return nil
}

